#!/usr/bin/env node
/**
 * generate-volunteer-pdf.mjs — HTML → PDF for volunteer applications
 *
 * Usage:
 *   node generate-volunteer-pdf.mjs <input.html> <output.pdf>
 *
 * The input HTML is typically generated by Claude from the template
 * at templates/volunteer-letter.html with all {{VARS}} replaced.
 *
 * Output saved to output/ directory.
 */

import { chromium } from 'playwright';
import { resolve, dirname, basename } from 'path';
import { readFile, writeFile, mkdir } from 'fs/promises';
import { existsSync } from 'fs';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));

async function generatePDF() {
  const args = process.argv.slice(2).filter(a => !a.startsWith('--'));
  const format = (process.argv.find(a => a.startsWith('--format=')) || '').split('=')[1] || 'a4';

  let [inputPath, outputPath] = args;

  if (!inputPath) {
    console.error('Usage: node generate-volunteer-pdf.mjs <input.html> [output.pdf]');
    process.exit(1);
  }

  inputPath = resolve(inputPath);

  // Default output path: output/<basename>.pdf
  if (!outputPath) {
    const base = basename(inputPath, '.html');
    outputPath = resolve(__dirname, 'output', `${base}.pdf`);
  } else {
    outputPath = resolve(outputPath);
  }

  await mkdir(dirname(outputPath), { recursive: true });

  if (!existsSync(inputPath)) {
    console.error(`File not found: ${inputPath}`);
    process.exit(1);
  }

  console.log(`Input:  ${inputPath}`);
  console.log(`Output: ${outputPath}`);
  console.log(`Format: ${format.toUpperCase()}`);

  let html = await readFile(inputPath, 'utf-8');

  const browser = await chromium.launch({ headless: true });
  try {
    const page = await browser.newPage();

    await page.setContent(html, {
      waitUntil: 'networkidle',    // wait for Google Fonts to load
      baseURL: `file://${dirname(inputPath)}/`,
    });

    // Ensure fonts are ready
    await page.evaluate(() => document.fonts.ready);

    const pdfBuffer = await page.pdf({
      format: format,
      printBackground: true,
      margin: { top: '0', right: '0', bottom: '0', left: '0' },
      preferCSSPageSize: false,
    });

    await writeFile(outputPath, pdfBuffer);

    const pdfString = pdfBuffer.toString('latin1');
    const pageCount = (pdfString.match(/\/Type\s*\/Page[^s]/g) || []).length;

    console.log(`\n✓ PDF gerado: ${outputPath}`);
    console.log(`  Páginas: ${pageCount}`);
    console.log(`  Tamanho: ${(pdfBuffer.length / 1024).toFixed(1)} KB`);

  } finally {
    await browser.close();
  }
}

generatePDF().catch(err => {
  console.error('Erro:', err.message);
  process.exit(1);
});
